const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = Number(input[0]);
const boots = Array.from({ length: 61 }, () => [0, 0]);

for (let i = 0; i < n; i++) {
  const size = Number(input[1 + i * 2]);
  const side = input[2 + i * 2] === 'D' ? 0 : 1;
  boots[size][side]++;
}

let pairs = 0;
for (const [right, left] of boots) {
  pairs += Math.min(right, left);
}

console.log(pairs);
